/* Exact problem-specific diagrams and paused, inspectable solution models. */
"use strict";
(() => {
let data;const players=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const load=()=>data??(data=fetch('problem-visual-models.json?v=question-visuals-3').then(r=>{if(!r.ok)throw Error('Problem model data unavailable');return r.json();}));
const el=(tag,txt,cls)=>{const e=document.createElement(tag);if(txt!==undefined)e.textContent=txt;if(cls)e.className=cls;return e;};
async function mount(host){if(host.dataset.loaded)return;const fallbackMarkup=host.innerHTML;host.dataset.loaded='loading';try{const all=await load(),m=all[host.dataset.problemVisual];if(!m)throw Error('Missing problem model');host.replaceChildren();host.append(el('h4','Visual solution aid'),el('p',m.reading,'problem-reading'));let i=0,timer;const stage=el('div',undefined,'problem-stage');stage.tabIndex=0;stage.setAttribute('aria-label','Scrollable question-specific diagram');const controls=el('div',undefined,'problem-controls'),buttons={};
 const pause=()=>{clearTimeout(timer);timer=null;if(buttons.play)buttons.play.textContent='Play';};
 const draw=()=>{stage.innerHTML=m.frames[i].html;stage.dataset.frame=i;for(const s of stage.querySelectorAll('svg')){if(s.viewBox.baseVal.width>900)s.style.minWidth=s.viewBox.baseVal.width+'px';DiagramLayout?.finish(s,{arrows:false});}caption.textContent=m.frames[i].caption;count.textContent=`Step ${i+1} of ${m.frames.length}`;seek.value=i;if(buttons.previous)buttons.previous.disabled=i===0;if(buttons.next)buttons.next.disabled=i===m.frames.length-1;MathLayout?.schedule();};
 const next=()=>{if(i>=m.frames.length-1){pause();return;}i++;draw();timer=setTimeout(next,1500/Number(speed.value));};
 const caption=el('p',undefined,'problem-caption');caption.setAttribute('aria-live','polite');const count=el('span',undefined,'problem-counter');const seek=el('input');seek.type='range';seek.min=0;seek.max=m.frames.length-1;seek.step=1;seek.setAttribute('aria-label','Choose a solution checkpoint');const speed=el('select');speed.setAttribute('aria-label','Solution playback speed');for(const v of [.5,1,2]){const o=el('option',v+'×');o.value=v;o.selected=v===1;speed.append(o);}
 if(m.frames.length>1){for(const [key,label] of [['restart','Restart'],['previous','Previous step'],['play','Play'],['next','Next step']]){const b=el('button',label);b.type='button';buttons[key]=b;controls.append(b);b.addEventListener('click',()=>{if(key==='play'){if(timer){pause();return;}players.forEach(p=>p.pause());if(i===m.frames.length-1)i=0;draw();buttons.play.textContent='Pause';timer=setTimeout(next,1500/Number(speed.value));}else{pause();i=key==='restart'?0:Math.max(0,Math.min(m.frames.length-1,i+(key==='next'?1:-1)));draw();}});}controls.append(el('label','Speed'),speed);host.append(controls);const progress=el('div',undefined,'problem-progress');progress.append(seek,count);host.append(progress);seek.addEventListener('input',()=>{pause();i=Number(seek.value);draw();});}
 host.append(stage,caption,el('p',m.scope,'problem-scope'));host.dataset.loaded='true';draw();const p={host,model:m,show:n=>{pause();i=n;draw();},pause,get index(){return i}};players.push(p);host.addEventListener('keydown',e=>{if(e.target.matches('input,select')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();pause();i=Math.max(0,Math.min(m.frames.length-1,i+(e.key==='ArrowRight'?1:-1)));draw();});
 }catch(e){host.innerHTML=fallbackMarkup;host.dataset.loaded='error';host.append(el('p','The interactive aid could not load. Its printed first diagram and full written solution remain available.'));console.error(e);}}
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)mount(e.target);else players.find(p=>p.host===e.target)?.pause();}),{rootMargin:'200px'});document.querySelectorAll('[data-problem-visual]').forEach(h=>observer.observe(h));
addEventListener('beforeprint',()=>{players.forEach(p=>p.pause());document.querySelectorAll('details.exam-solution').forEach(e=>{e.dataset.problemPrintOpen=String(e.open);e.open=true;});});
addEventListener('afterprint',()=>document.querySelectorAll('details[data-problem-print-open]').forEach(e=>{e.open=e.dataset.problemPrintOpen==='true';delete e.dataset.problemPrintOpen;}));
document.addEventListener('visibilitychange',()=>{if(document.hidden)players.forEach(p=>p.pause());});
window.ProblemVisuals={ready:mount,players};
})();
